    const eagerCtx = new Context()
    await eagerCtx.plugin(SessionStore)
    await expect(eagerCtx.plugin(SqliteSessionQueryEngine, { path }))
      .rejects.toThrow(expectCode('SESSION_QUERY_INDEX_FAILED'))
